[STAThread]static int Main(){try{string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-involucros");Directory.CreateDirectory(dir);var rows=EnclosureCatalog.Import(Path.Combine(dir,"abb-mistral41w.csv"));Check(rows.Count==3&&rows[0].ModulePitchMm==17.5&&rows[1].RowPitchMm==125,"real documented module/rail geometry");var p=Project.CreateSample();var b=p.Boards[0];var c1=b.Circuits[0];var c2=b.Circuits[1];Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"generic enclosure not real catalog acceptance");EnclosureCatalog.Apply(p,b,rows[0]);Check(b.Enclosure.WidthMm==297&&b.Enclosure.HeightMm==262&&b.Enclosure.Rows==1&&b.Enclosure.ModulesPerRow==12,"real outer dims and explicit usable count");Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"generic2module defaults not proven footprint");EnclosureCatalog.ApplyFootprint(p,b,c1,Footprint(6),0,0);var declared=Footprint(6);EnclosureCatalog.ApplyFootprint(p,b,c2,declared,0,0);var good=EnclosureCatalog.Evaluate(p,b);Check(good.Accepted,good.Detail);Check(Enclosures.Layout(b).First(x=>x.Circuit==c2).Column==7,"two6modules fit12 exactly");declared.WidthModules=50;Check(c2.DinFootprint.WidthModules==6,"footprint snapshot copied");c1.DinFootprint.ModulePitchMm=18;Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"mismatched module pitch cannot approve enclosure");c1.DinFootprint.ModulePitchMm=17.5;var badPitch=Footprint(6);badPitch.ModulePitchMm=0;Reject(()=>EnclosureCatalog.ApplyFootprint(p,b,c1,badPitch,0,0),"zero module pitch rejected atomically");string valid=Path.Combine(dir,"um-trilho.circuito");p.Save(valid);File.WriteAllText(Path.Combine(dir,"um-trilho.svg"),EnclosureCatalog.Svg(p,b,"Frontal1×12"));var restored=Project.Load(valid);Check(EnclosureCatalog.Evaluate(restored,restored.Boards[0]).Accepted,"catalog footprint and hardware context reopen");Check(EnclosureCatalog.Svg(p,b,"Frontal1×12")==EnclosureCatalog.Svg(restored,restored.Boards[0],"Frontal1×12"),"SVG deterministic after reopen");Check(EngineeringReport.Memory(p,Engineering.Analyze(p))==EngineeringReport.Memory(restored,Engineering.Analyze(restored)),"memory exact after reopen");Check(EngineeringReport.Memory(p,Engineering.Analyze(p)).Contains("INVÓLUCRO E OCUPAÇÃO FRONTAL"),"catalog in memory");var selected=EngineeringReport.Memory(p,Engineering.Analyze(p),new System.Collections.Generic.HashSet<string>(new[]{c1.Id}));Check(selected.Contains(c2.Id+": módulos=6"),"selected circuit retains whole shared occupancy");Check(!EngineeringReport.Memory(p,Engineering.Analyze(p),new System.Collections.Generic.HashSet<string>()).Contains("INVÓLUCRO E OCUPAÇÃO FRONTAL"),"empty report selection omits enclosure");c1.DinRow=c2.DinRow=1;c1.DinColumn=1;c2.DinColumn=6;Check(!EnclosureCatalog.Evaluate(p,b).Accepted&&EnclosureCatalog.Evaluate(p,b).Issues.Any(x=>x.Contains("sobreposição")),"manual overlap invalid");File.WriteAllText(Path.Combine(dir,"sobreposicao.svg"),EnclosureCatalog.Svg(p,b,"Sobreposição"));Enclosures.AutoArrange(b);EnclosureCatalog.ApplyFootprint(p,b,c2,Footprint(4),1,3);Check(Enclosures.Layout(b).First(x=>x.Circuit==c1).Column==7,"manual slots reserved before automatic");Check(EnclosureCatalog.Evaluate(p,b).Accepted,"manual/auto mixed occupancy valid");EnclosureCatalog.ApplyFootprint(p,b,c2,Footprint(7),0,0);Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"13modules exceed1x12");EnclosureCatalog.Apply(p,b,rows[1]);Check(EnclosureCatalog.Evaluate(p,b).Accepted,"13modules fit2x12 not derived from outer width");Check(Enclosures.Layout(b).First(x=>x.Circuit==c2).Row==2,"row2 chosen for7modules");p.Save(Path.Combine(dir,"dois-trilhos.circuito"));File.WriteAllText(Path.Combine(dir,"dois-trilhos.svg"),EnclosureCatalog.Svg(p,b,"Frontal2×12"));c2.DinRow=3;c2.DinColumn=1;Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"manual row outside catalog");Enclosures.AutoArrange(b);double oldCurrent=c1.BreakerA;c1.BreakerA+=1;Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"hardware change invalidates envelope confirmation");c1.BreakerA=oldCurrent;c1.DinModules=5;Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"manual width diverges from evidence");c1.DinModules=6;c1.DinFootprint.CoversAccessories=null;Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"unknown accessories not covered");c1.DinFootprint.CoversAccessories=true;double width=b.Enclosure.WidthMm;b.Enclosure.WidthMm+=1;Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"generic geometry mutation invalidates factory snapshot");b.Enclosure.WidthMm=width;var original=b.EnclosureCatalogSelection.Rating.Source;b.EnclosureCatalogSelection.Rating.Source="PREENCHER";Check(!EnclosureCatalog.Evaluate(p,b).Accepted,"missing source remains pending");b.EnclosureCatalogSelection.Rating.Source=original;var old=c1.DinFootprint;Reject(()=>EnclosureCatalog.ApplyFootprint(p,b,c1,Footprint(0),0,0),"zero footprint rejected");Check(Object.ReferenceEquals(old,c1.DinFootprint)&&c1.DinModules==6,"invalid footprint atomic");var before=b.Enclosure;var invalid=rows[0].Copy();invalid.WidthMm=Double.NaN;Reject(()=>EnclosureCatalog.Apply(p,b,invalid),"invalid catalog geometry rejected");Check(Object.ReferenceEquals(before,b.Enclosure),"invalid catalog apply preserves spec");var engine=c1.DinFootprint.Engine;c1.DinFootprint.Engine="future";Reject(p.Validate,"unknown footprint revision");c1.DinFootprint.Engine=engine;string csv=Path.Combine(dir,"roundtrip.csv");EnclosureCatalog.Export(rows,csv);EnclosureCatalog.Export(rows,csv);Check(EnclosureCatalog.Import(csv).Count==3&&File.Exists(csv+".bak"),"real catalog CSV roundtrip/backup");File.WriteAllText(Path.Combine(dir,"bad.csv"),File.ReadAllText(csv).Replace("\"2\";\"12\"","\"2.5\";\"12\""));Reject(()=>EnclosureCatalog.Import(Path.Combine(dir,"bad.csv")),"fractional row count rejected");Check(File.ReadAllText(valid).Contains("enclosure-catalog-v1"),"capability present");var copy=ProjectEditing.DuplicateCircuit(p,b,c1);Check(copy.DinFootprint!=c1.DinFootprint&&copy.DinFootprint.WidthModules==6,"duplicate footprint independent");b.Circuits.Remove(copy);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrEmpty(previous)){var asm=Assembly.LoadFile(Path.GetFullPath(previous));bool refused=false;try{asm.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{valid});}catch(TargetInvocationException ex){refused=ex.InnerException is InvalidDataException;}Check(refused,"actual previous38 reader refuses new capability");}int changes=0;using(var form=new EnclosureCatalogForm(p,b,()=>changes++)){Check(!form.Changed&&changes==0,"open no mutation");form.ApplyRating(rows[2]);Check(form.Changed&&changes==1&&b.Enclosure.Rows==3,"catalog apply immediately notifies autosave");form.ApplyFootprint(c2,Footprint(7),2,2);Check(changes==2&&form.Evaluate().Accepted,"footprint/position apply immediately notifies");form.AutoArrange();Check(changes==3&&form.Evaluate().Accepted,"autoarrange clears manual position and notifies");form.AutoArrange();Check(changes==3,"unchanged arrangement no revision");p.Save(Path.Combine(dir,"tres-trilhos.circuito"));File.WriteAllText(Path.Combine(dir,"tres-trilhos.svg"),EnclosureCatalog.Svg(p,b,"Frontal3×12"));if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(5,5);form.Show();Application.DoEvents();form.Refresh();form.Update();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(dir,"involucro-real.png"));}form.Hide();}}var doc=new XmlDocument();doc.XmlResolver=null;doc.Load(Path.Combine(dir,"tres-trilhos.svg"));Check(doc.InnerText.Contains("sem cotas de montagem/furação")&&doc.InnerText.Contains("1SPE007717F0610"),"SVG real source and schematic limits explicit");Console.WriteLine("PASS: "+n+" enclosure-catalog assertions");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
